window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-pediatria-med-ped-01"]={"block":"med:med-pediatria-med-ped-01","label":"MED · MED PED 01","count":53,"questions":[{"id":"med-pediatria-med-ped-01-251925","number":"251925","sourceNumber":"251925","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"As doenças exantemáticas na infância e são queixas bem frequentes nos consultórios\nde pronto atendimento pediátrico. Leia as\ncolunas abaixo e marque a alternativa que contem a\nassociação CORRETA, entre a doença e sua característica: I. Sarampo. II. Exantema súbito. III.\nVaricela. IV. Eritema infeccioso. V. Escarlatina. 1. Face esbofetada. 2. Polimorfismo das lesões na\nmesma região do corpo. 3. Manchas de Koplik. 4. Sinal de Filatov. 5. Exantema surge após o\ncessar da febre.","options":{"A":"I-4; II-1; III- 2; IV- 5; V- 3.","B":"I-4; II-5; III- 2; IV- 1; V- 3.","C":"I-3; II-1; III-5; IV- 3; V- 2.","D":"I-3; II-5; III- 2; IV- 1; V- 4."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-29339","number":"29339","sourceNumber":"29339","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Qual das doenças exantemáticas abaixo é causa mais comum de convulsão febril:","options":{"A":"Rubéola","B":"Eritema infeccioso","C":"Exantema súbito","D":"Sarampo","E":"Varicela"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-29341","number":"29341","sourceNumber":"29341","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"As adenomegalias são muito frequentes na infância, admite-se linfonodos palpáveis,\ndentro de determinado diâmetro, em algumas\ncadeias em crianças saudáveis que não são\npassíveis de investigação laboratorial. Qual a cadeia linfonodal que deve ser investigada ao menor\ntamanho:","options":{"A":"Supraclavicular","B":"Cervical","C":"Axilar","D":"Inguinal","E":"Submandibular"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-134305","number":"134305","sourceNumber":"134305","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um adolescente com quadro febril e dor de garganta há 2 dias procura atendimento no\nPronto-socorro. Ao exame observa-se hipertrofia e hiperemia de amígdalas com exsudato\nesbranquiçado. Qual dos sinais assinalados a seguir NÃO é frequentemente associado ao quadro\nde mononucleose infecciosa?","options":{"A":"Hepatoesplenomegalia.","B":"Petéquias no palato.","C":"Edema palpebral.","D":"Artrite exsudativa."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-107604","number":"107604","sourceNumber":"107604","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um lactente de duas semanas de vida apresenta temperatura de 38,9ºC. A gestação e\no parto foram sem complicações. O lactente\napresenta irritação e agitação com uma frequência\ncardíaca de 170bpm e frequência respiratória de 40irpm. A fontanela anterior está abaulada, mas\nnão há rigidez de nuca; o restante do exame físico não apresenta alterações. Qual das opções a\nseguir é o tratamento mais adequado para o lactente?","options":{"A":"Encorajar a ingestão de líquidos e reavaliar com 24hs.","B":"Realizar Punção lombar, hemocultura, urinocultura e determinar internação hospitalar.","C":"Prescrever ceftriaxona IM e reavaliar com 1 semana no ambulatório.","D":"Prescrever amoxicilina oral e reavaliar com 1 mês no ambulatório."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-60843","number":"60843","sourceNumber":"60843","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Adolescente de 15 anos, grávida de 40 semanas, deu entrada na maternidade em\ntrabalho de parto. Realizou nove consultas de pré-natal, sem intercorrência durante gestação.\nGesta 1, Para 0, Aborto 0. Sorologias para HIV, toxoplasmose, sífilis, rubéola não reatoras.\n\nApresentava ao exame físico máculas eritematosas intensas pruriginosas que evoluíram para um\nestágio papular para formar vesículas claras repletas de líquidos, localizadas em face, tronco e\nabdômen. Sugiram há 02 dias (sic). A rotina na maternidade em relação à doença materna, e\nconduta ao recém-nascido é isolamento de contato dos demais recém-nascidos:","options":{"A":"Aleitamento artificial e administrar aciclovir","B":"Aleitamento artificial, administrar antibióticos e aciclovir","C":"Manter aleitamento materno, administrar antibiótico","D":"Isolar recém-nascido e administrar leite artificial e imunoglobulinas","E":"Manter aleitamento materno e administrar imunoglobulina para varicela-zoster até 96 horas"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-60879","number":"60879","sourceNumber":"60879","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Pré-escolar 2 anos chega ao PS com história de febre baixa, cefaleia e sintomas de\numa infecção leve do trato respiratório\nsuperior. No início, sua mãe relata rubor facial e eritematoso\nproximais, na forma de um eritema macular difuso. As palmas das mãos e as plantas dos pés são\npoupadas, e a erupção tende ser mais intensa nas superfícies extensoras. Sem queixa de febre e\nnão parece enferma. Qual a hipótese diagnóstica:","options":{"A":"Rubéola","B":"Sarampo","C":"Parvovírus B19","D":"Farmacodermia","E":"Infecção bacteriana"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-34154","number":"34154","sourceNumber":"34154","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"No sarampo, as manchas de Koplik são os sinais patognomônicos que aparecem\nquantos dias antes do início da fase de\nerupção?","options":{"A":"1 a 4 dias.","B":"5 a 7 dias.","C":"8 a 10 dias.","D":"10 a 12 dias.","E":"12 a 15 dias."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-26593","number":"26593","sourceNumber":"26593","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"O período de incubação da mononucleose infecciosa em adolescente é:","options":{"A":"10 a 20 dias","B":"5 a 10 dias","C":"15 a 30 dias","D":"30 a 35 dias","E":"30 a 50 dias"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-26604","number":"26604","sourceNumber":"26604","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"O que caracteriza o sarampo?","options":{"A":"Precedido por 3 dias de febre em lactentes","B":"Febre, tosse, congestão ocular, espirros, enantema","C":"Nódulos eritematosos dolorosos na face anterior das pernas","D":"Adenopatia cervical e occipital em escolar","E":"Face de criança esbofeteada, afebril"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-9991","number":"9991","sourceNumber":"9991","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Criança de 5 anos apresenta febre de 40ºC, com duração de 1 a 2 semanas, remitente\ne refratária a antibióticos, tendo ainda\nmanifestações típicas como: congestão conjuntival bulbar\nbilateral em geral sem exsudato; eritema da mucosa oral e faríngea com língua de \"framboesa\";\nlábios secos e rachados; eritema e tumefação das mãos e pés; exantema maculopapuloso e\nlinfadenopatia cervical não supurativa, em geral unilateral. Com uma ou três semanas apresentam\ndescamações dos dedos das mãos e pés. Qual a patologia mais provável?","options":{"A":"Escarlatina.","B":"Síndrome do choque tóxico.","C":"Sarampo.","D":"Farmacodermia.","E":"Doença de Kawasaki."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-10008","number":"10008","sourceNumber":"10008","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Associe as doenças exantemáticas aos sinais patognomônicos: (1) Sarampo; (2)\nEscarlatina; (3) Eritema infeccioso; (4) Exantema súbito; (5) Monucleose. ( ) Tríade: amigdalite\nmembranosa, febre, linfoadenopatia e esplenomegalia; ( ) Exantema facial em forma de borboleta\n(face esbofetada); ( ) Palidez peribucal (sinal de Filatow); ( ) Febre desaparece com início do\nexantema; ( ) Mancha de Koplik.","options":{"A":"2, 5, 3, 1, 4.","B":"1, 5, 4, 3, 2.","C":"4, 1, 2, 5, 3.","D":"1, 4, 5, 3, 2.","E":"5, 3, 2, 4, 1."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-34974","number":"34974","sourceNumber":"34974","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente, 12 anos de idade, sexo feminino, internada com quadro de febre há duas\nsemanas, com edema periorbitário bilateral, tosse improdutiva, dor de garganta. Ao exame, BEG,\nfebril, descorada (+/4), edema periorbitário bilateral, hiperemia de orofaringe, gânglios palpáveis,\nmóveis, dolorosos, de consistência fibroelástica, não aderidos a planos profundos, em cadeias\ncervical posterior, retroauricular, axilar e inguinal. Abdome com discreta hepatoesplenomegalia.\n\nHemograma com 15400 leucócitos, 30% segmentados, 50% linfócitos, 20% de atípicos. TGO e\nTGP pouco elevadas. A paciente provavelmente apresenta um quadro de:","options":{"A":"hepatite vírus C.","B":"calazar.","C":"esquistossomose hepatoesplênica.","D":"mononucleose infecciosa.","E":"doença do soro."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-34926","number":"34926","sourceNumber":"34926","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Menino, quatro anos de idade, é atendido no mês de fevereiro no Posto de Saúde com\nhistória de febre alta (temperatura axilar de até 39,5°C) há 24 horas, dor de garganta, vômitos e\ndor\nde cabeça. Ao exame físico, encontra-se febril (temperatura de 39°C), em bom estado geral,\nrevelando apenas faringite hiperemiada e adenomegalia cervical. O médico do Posto prescreve\nampicilina por via oral e solicita retorno após 24 horas. Cerca de 18 horas após, a criança retorna\ncom uma erupção cutânea micropapular, localizada em face e tronco, poupando a região perioral,\navermelhada e que clareia a digitopressão. O exame da orofaringe demonstra língua recoberta por\numa camada branca, com áreas hiperemiadas e com hipertrofia de papilas, além de placas\nesbranquiçadas em amígdalas. O exantema é mais acentuado nas pregas poplíteas, formando\nlinhas. O diagnóstico clínico mais provável é:","options":{"A":"mononucleose infecciosa.","B":"enterovirose não pólio.","C":"escarlatina.","D":"eritema infeccioso.","E":"sarampo."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-34927","number":"34927","sourceNumber":"34927","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Menino, quatro anos de idade, é atendido no mês de fevereiro no Posto de Saúde com\nhistória de febre alta (temperatura axilar de até 39,5°C) há 24 horas, dor de garganta, vômitos e\ndor\nde cabeça. Ao exame físico, encontra-se febril (temperatura de 39°C), em bom estado geral,\nrevelando apenas faringite hiperemiada e adenomegalia cervical. O médico do Posto prescreve\nampicilina por via oral e solicita retorno após 24 horas. Cerca de 18 horas após, a criança retorna\ncom uma erupção cutânea micropapular, localizada em face e tronco, poupando a região perioral,\navermelhada e que clareia a digitopressão. O exame da orofaringe demonstra língua recoberta por\numa camada branca, com áreas hiperemiadas e com hipertrofia de papilas, além de placas\nesbranquiçadas em amígdalas. O exantema é mais acentuado nas pregas poplíteas, formando\nlinhas. Apesar de não comprovarem o diagnóstico, são achados clínicos que caracterizam o quadro\ndescrito, exceto:","options":{"A":"sinal de Filatov.","B":"língua em framboesa.","C":"sinal de Hoagland.","D":"descamação em placas.","E":"exantema micropapular."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-27471","number":"27471","sourceNumber":"27471","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente, 12 anos de idade, sexo feminino, é internada com quadro de febre há 2\nsemanas, com edema periorbitário bilateral, tosse improdutiva, dor de garganta. Ao exame, BEG,\nfebril, descorada (+/4). Edema periorbitário bilateral, hiperemia de orofaringe; gânglios palpáveis,\nmóveis, dolorosos, de consistência fibroelástica, não aderidos a planos profundos, em cadeias\ncervical posterior, retroauricular, axilar e inguinal. Abdome com discreta hepatoesplenomegalia.\n\nHemograma com 15.400 leucócitos, 30% segmentados, 50% linfócitos, 20% de atípicos. TGO e\nTGP pouco elevadas. O diagnóstico mais provável é:","options":{"A":"hepatite vírus A.","B":"calazar.","C":"esquistossomose hepatoesplênica.","D":"mononucleose infecciosa.","E":"doença do soro."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-27473","number":"27473","sourceNumber":"27473","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente, 12 anos de idade, sexo feminino, é internada com quadro de febre há 2\nsemanas, com edema periorbitário bilateral, tosse improdutiva, dor de garganta. Ao exame, BEG,\nfebril, descorada (+/4). Edema periorbitário bilateral, hiperemia de orofaringe; gânglios palpáveis,\nmóveis, dolorosos, de consistência fibroelástica, não aderidos a planos profundos, em cadeias\ncervical posterior, retroauricular, axilar e inguinal. Abdome com discreta hepatoesplenomegalia.\n\nHemograma com 15.400 leucócitos, 30% segmentados, 50% linfócitos, 20% de atípicos. TGO e\nTGP pouco elevadas. O exame a ser solicitado para elucidar o diagnóstico é:","options":{"A":"mielograma.","B":"biópsia hepática.","C":"anticorpos específicos para EBV.","D":"dosagem de IGE sérica.","E":"sorologia para hepatite A."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-134712","number":"134712","sourceNumber":"134712","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Dentre as abaixo, marque a alternativa que descreve todas as fases do exantema da\nvaricela.","options":{"A":"Mácula, pápula, vesícula e crosta.","B":"Mácula, vesícula, pústula e crosta.","C":"Pápula, pústula e crosta.","D":"Vesícula e crosta."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-111863","number":"111863","sourceNumber":"111863","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente de 5 anos é trazido ao Posto de Saúde pela mãe que refere que criança\niniciou há 1 dia ?bolinhas pelo corpo?, que\nse iniciaram na face, associada a prurido intenso e febre\nde 38°C. Ao exame, apresenta enantema em palato, lesões polimórficas nucleares disseminadas\nde forma centrípeta. Qual é o PROVÁVEL diagnóstico do paciente?","options":{"A":"Parvovirose.","B":"Rubéola.","C":"Sarampo.","D":"Varicela."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-102167","number":"102167","sourceNumber":"102167","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"A mãe de uma criança de dois anos de idade relata ao médico que sua filha esteve há\ncinco dias, por quatro horas, em convívio próximo com uma colega de creche da mesma idade, que\nno momento atual está com sarampo. Qual medida de proteção deve ser aplicada?","options":{"A":"Vacina de vírus atenuado contra o sarampo.","B":"Imunoglobulina humana normal.","C":"Nenhuma medida é necessária.","D":"Quarentena do comunicante."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-51296","number":"51296","sourceNumber":"51296","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Menino de 3 anos, com febre alta há 8 dias, apresenta linfoadenomegalia de cadeia\ncervical anterior direita, eritema de orofaringe,\neritema da língua com papilas proeminentes,\nconjuntivite bilateral não exsudativa, exantema polimorfo troncular e inchaço endurado nas mãos e\npés. Tratado com cefalosporina de 1ª geração, quadro evolui sem melhora. Apresenta, 3 semanas\napós o início do quadro, massa pulsátil em região axilar direita. Qual exame é imprescindível para\nconduzir o paciente adequadamente?","options":{"A":"Ecocardiograma bidimensional com Doppler.","B":"Tomografia computadorizada da massa axilar.","C":"Exérese cirúrgica para biópsia da massa axilar.","D":"Punção aspirativa da massa guiada por ultrassom."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-32544","number":"32544","sourceNumber":"32544","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"A síndrome de Kawasaki e a escarlatina apresentam muitas manifestações em comum.\nEm relação a essas doenças, analise as\nafirmativas abaixo: I - ambas apresentam envolvimento\ncutâneo e linfonodal; II - a adenomegalia cervical e a conjuntivite não exsudativa são sinais\ndiagnósticos na Síndrome de Kawasaki; III - a presença de estreptococos do grupo A na orofaringe\nconfirma o diagnóstico da escarlatina e testes sorológicos são úteis no diagnóstico dessas\ndoenças; IV - o tratamento com imunoglobulina endovenosa e ácido acetilsalicílico reduz a\nprevalência de anormalidades cardíacas na Síndrome de Kawasaki. Estão corretas somente as\nafirmativas:","options":{"A":"I, II e III.","B":"I, II, e IV.","C":"II, III e IV.","D":"II e III.","E":"III e IV."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-30903","number":"30903","sourceNumber":"30903","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Criança de 2 anos com febre, anorexia, apresentando vesículas nas mãos e nos pés e\nestomatite na cavidade oral. O agente etiológico mais provável é:","options":{"A":"Herpes tipo I.","B":"Herpes tipo II.","C":"Vírus da Varicela-Zóster.","D":"Coxsackievírus.","E":"Parvovírus B19."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-36968","number":"36968","sourceNumber":"36968","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Garoto de 9 anos apresentou vermelhidão nas bochechas e, posteriormente, exantema\nde aspecto rendilhado no tronco e nos membros.\nNão apresentou febre e evoluiu com melhora\nespontânea após alguns dias. No entanto, este quadro voltou a se repetir por mais duas vezes num\nperíodo de 3 meses, coincidindo com ida à praia. Qual o diagnóstico mais provável?","options":{"A":"Urticária crônica.","B":"Queimadura solar.","C":"Eritema infeccioso.","D":"Dermatite de contato."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-22951","number":"22951","sourceNumber":"22951","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Criança de 5 anos de idade há 3 meses apresenta adenopatia cervical esquerda, cerca\nde 4 cm de diâmetro, de crescimento lento,\nindolor, sem sinais flogísticos, aderentes aos planos\nprofundos, consistência endurecida, acompanhado de febre diária. Que achados indicariam a\nbiópsia desse gânglio?","options":{"A":"febre persistente e o tamanho","B":"tempo de evolução e a consistência","C":"ausência de sinais flogísticos e a localização","D":"localização do gânglio e a consistência","E":"tamanho do gânglio e idade do paciente"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-27702","number":"27702","sourceNumber":"27702","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Uma menina de 5 anos de idade é trazida ao seu pediatra com uma febre que dura\ncinco dias. Sua mãe relata que as imunizações\nde sua filha estão em dia e que ela não tem\nproblemas crônicos de saúde. Sinais vitais mostram temperatura de 38,9°C, pulso 111 ppm,\nfrequência respiratória de 16 ipm e pressão arterial 122/65 mmHg. Ao exame, ela apresenta língua\nvermelha e edemaciada, linfonodos cervicais palpáveis, uma erupção cutânea difusa inespecífica\nmaculopapular, e injeção escleral bilateral. A melhor conduta neste caso é iniciar:","options":{"A":"antibioticoterapia intravenosa","B":"terapia antiviral oral","C":"imunoglobulina intravenosa","D":"esteroides intravenosos","E":"plasmaferese"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-7286","number":"7286","sourceNumber":"7286","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Uma criança apresenta exantema eritematoso puntiforme, palidez perioral e linhas nas\ndobras de flexão, com posterior descamação extensa. Esses achados são característicos do\ndiagnóstico de:","options":{"A":"Eritema infeccioso;","B":"Meningococcemia;","C":"Escarlatina;","D":"Sarampo;","E":"Síndrome de Kawasaki."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-6937","number":"6937","sourceNumber":"6937","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Uma criança de 15 meses apresentou febre elevada por 3 dias, tendo ocorrido\nconvulsão febril no primeiro dia da doença.\nPermaneceu com bom estado geral. No quarto dia,\nexantema maculopapular generalizado, não voltando a apresentar febre. O agente etiológico mais\nprovável é:","options":{"A":"Vírus da Rubéola.","B":"Herpes tipo 6.","C":"Estreptococo do grupo A.","D":"Vírus do sarampo.","E":"Parvovírus B19."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-13477","number":"13477","sourceNumber":"13477","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Menina de 13 anos, há 1 semana vem apresentando palidez, icterícia, urina escura, dor\nabdominal e febre. Exames laboratoriais: Anemia, anisocitose, poiquilocitose, macrocitose e\nreticulocitose. Qual agente infeccioso é o menos provável causador do quadro acima?","options":{"A":"Epstein-Barr.","B":"Citomegalovírus.","C":"Vírus Varicela--Zóster.","D":"Parvovírus B19.","E":"Mycoplasma pneumoniae."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-255720","number":"255720","sourceNumber":"255720","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um paciente de 11 anos de idade apresenta linfonodomegalia cervical, dor de garganta,\nfebre, esplenomegalia e perda de peso. O médico\nentão solicita exames que demonstram\nlinfocitose linfócitos atípicos. Com base nesse caso e nos conhecimentos médicos correlatos, julgue\no item a seguir. Tratamento com aciclovir tem ótimos resultados na redução de tempo dos\nsintomas, sendo demonstrado em ensaios clínicos randomizados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-7568","number":"7568","sourceNumber":"7568","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Pré-escolar, do sexo feminino, com quatro anos de idade, branca, foi levada por sua\nmãe ao pronto-socorro por apresentar há\ndois dias diversas vesículas por todo corpo, associadas a\nprurido intenso e febre. Esta última está presente há três dias. Foi prescrito antialérgico por via\noral\ne banhos de permanganato de potássio, e, após orientações gerais para a mãe, a criança foi\nliberada. Quatro dias após, a criança retornou ao pronto-socorro com dor de garganta, persistência\nda febre, inapetência e tosse seca. Ao exame clínico nessa ocasião, a criança estava febril\n(temperatura axilar igual a 39,1°C), orientada, taquipneica (24 ipm), amígdalas hiperemiadas, com\nplacas esbranquiçadas, halitose e língua saburrosa. Apresentava lesões crostosas por todo corpo,\ncom predomínio em face, que variam em tamanho de 0,3 a 0,8 cm de diâmetro associado a um\nrash cutâneo. Com base nessa situação hipotética, assinale a alternativa CORRETA:","options":{"A":"A criança apresenta uma infecção secundária que é uma complicação comum da doença.","B":"Deve-se internar a criança e iniciar cefalosporina de terceira geração associada a um\naminogliosídeo.","C":"Está indicada, nesta paciente, a aplicação da imunoglobulina hiperimune antivaricela.","D":"A criança pode ser liberada para casa apenas com orientações para higiene da boca com água\nbicarbonatada e uso de antialérgicos via oral.","E":"Caso a criança frequente creche ou escola, ela não precisa ser afastada desses locais no\nmomento."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-8582","number":"8582","sourceNumber":"8582","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Adolescente de 15 anos de idade cursa com febre baixa, exantema maculopapuloso\nque se iniciou na face, no couro cabeludo e\npescoço, espalhando-se, posteriormente, para todo o\ncorpo e linfonodomegalia retroauricular e cervical. O diagnóstico é de:","options":{"A":"Mononucleose.","B":"Rubéola.","C":"Roséola.","D":"Doença de Lyme.","E":"Sarampo."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-352327","number":"352327","sourceNumber":"352327","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Idade menor que 12 meses e etnia branca são fatores que indicam coleta de urina em\nmeninas com FSSL.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-352325","number":"352325","sourceNumber":"352325","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um paciente foi levado ao pronto-socorro apresentando um quadro de febre, tosse\nacompanhada de rinorreia hialina,\ncefaleia, mal-estar e intensa prostração por três dias. Devido à\nausência de uma piora progressiva e à elevação da temperatura para 39 °C, o pai administrou\ndipirona em dose adequada ao peso e trouxe o paciente para avaliação médica. No exame físico, o\npaciente se encontra em estado geral regular, hipodinâmico, mas cooperativo. Na avaliação da\ncavidade oral, observa-se hiperemia na orofaringe, além de pequenas máculas branco-azuladas,\ncom aproximadamente 1 mm de diâmetro, localizadas na mucosa jugal próxima aos molares,\nconforme ilustrado na imagem abaixo. Considerando que as imagens apresentadas, julgue o item A\nProteína C Reativa (PCR) com valores superiores a 20 mg/L é um marcador inflamatório mais\npreciso do que o leucograma em lactentes com menos de 2 meses de idade com FSSL,\nparticularmente na detecção de bacteremia e meningite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-291484","number":"291484","sourceNumber":"291484","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um paciente do sexo masculino, 3 anos de idade, é levado a serviço de emergência em\ndecorrência de febre e exantema há 7 dias. Mãe relata que a febre é diária e chegou a 39 ºC. O\nexantema surgiu há 2 dias. O paciente já passou por outros serviços de emergência sem conseguir\nfechar diagnóstico. Nega doenças prévias. Desenvolvimento normal para a idade. Ao exame,\nmostra-se em regular estado geral, descorado 1+/4+, febril (38,5 ºC), acianótico e hidratado.\n\nPresença de exantema maculopapular e edema e hiperemia nas mãos e pés, rash em tronco e\nperíneo, bem como de hiperemia conjuntival bilateral. Cavidade oral revela fissura em lábios. Há\nlinfonodomegalia cervical, unilateral direita, com 2 cm de diâmetro. Aparelho cardiovascular,\nrespiratório e abdome sem anormalidades. Considerando a história descrita acima, assinale a\nalternativa que contém o tratamento indicado.","options":{"A":"Imunoglobulina venosa.","B":"Anti-inflamatório não esteroidal.","C":"Antibioticoterapia.","D":"Plasmaférese."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-351605","number":"351605","sourceNumber":"351605","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Considere o caso a seguir: Lactente de 1 ano e 7 meses, masculino, apresenta quadro\nde febre iniciado há 6 dias, frequentemente\nacima de 39°C, associado ao aparecimento de\nexantema em tronco e a perda de apetite. Hiperemia conjuntival, lábios fissurados e bastante\nhiperemiados. Ao exame físico, o pediatra observa edemas em mãos e pés, além de proeminente\nlinfonodomegalia cervical bilateral, com maior linfonodo com cerca de 2 cm. O paciente\napresentava-se sem esforço respiratório, e sem alterações de ausculta pulmonar ou cardíaca.\n\nPreocupado com o quadro, o pediatra recomenda a internação da criança. Sobre o quadro acima\ndescrito, assinale a alterativa CORRETA:","options":{"A":"Recomenda-se a prescrição de imunoglobulina e ácido acetilsalicílico em dose anti-inflamatória.","B":"A despeito de não haver sopro cardíaco, face o quadro acima descrito a principal hipótese\ndiagnóstica é a de endocardite, provavelmente\nrelacionada a quadro de escarlatina incorretamente\nabordado.","C":"Os achados são característicos da miocardite causada pelo vírus da dengue, e exames\nlaboratoriais demonstrando plaquetose e aumento dos\nníveis de proteína C reativa podem ajudar a\nconsolidar o diagnóstico.","D":"Os achados são sugestivos de doença causada por vírus Coxsackie, sendo recomendado\napenas tratamento de suporte."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-255658","number":"255658","sourceNumber":"255658","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Qual entre os abaixo pode ser considerado sinal de alerta de complicações do Sarampo\napós o aparecimento do exantema? MARQUE A\nCORRETA:","options":{"A":"Dermatite ocre.","B":"Febre por mais de 3 dias.","C":"Plaquetopenia.","D":"Artralgia migratória."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-234451","number":"234451","sourceNumber":"234451","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Em relação ao sarampo, assinale a alternativa INCORRETA:","options":{"A":"É uma doença viral, infecciosa aguda, potencialmente grave, transmissível, extremamente\ncontagiosa e bastante comum na infância.","B":"A transmissão ocorre de forma direta, por meio de secreções nasofaríngeas expelidas ao tossir,\nespirrar, falar ou respirar.","C":"Para os profissionais de saúde é exigido o registro no cartão vacinal de no mínimo duas doses\nde vacinas contra o sarampo.","D":"Somente os casos confirmados devem ser registrados no Sistema de Informação de Agravos de\nNotificação (Sinan)."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-27392","number":"27392","sourceNumber":"27392","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"J.P.P, 7 anos , masculino, iniciou exantema em face com lesões maculopapulares que\nlogo confluíram em regiões malares (aspecto de asa de borboleta). Após 2 dias evoluiu com\nexantema em membros superiores e inferiores. Não apresentou febre e queixava-se de artralgia.\nSem adenomegalias. O hemograma apresentava discreta leucocitose e eosinofilia. Assinale a\nmelhor alternativa diagnóstica para o caso clínico descrito:","options":{"A":"Rubéola.","B":"Mononucleose infecciosa.","C":"Roséola infantil.","D":"Eritema infeccioso","E":"Sarampo."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-201748","number":"201748","sourceNumber":"201748","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"As infecções virais são frequentemente associadas a manifestações cutâneas,\nprincipalmente em crianças, nas quais elas são a causa mais comum de exantemas. Em\ndermatoses causadas por vírus:","options":{"A":"O eritema infeccioso, ou quinta doença, é causado pelo herpesvírus humano tipo 6 e\nmanifesta-se por máculas petequiais eritematosas no palato mole.","B":"A roséola infantil, ou exantema súbito, é causada pelo parvovírus humano B19 e manifesta-se\npor febre baixa de 3-5 dias de evolução.","C":"O sarampo é causado por um vírus RNA da família Paramyxoviridae e apresenta-se com um\npródomo de febre, tosse, congestão nasal e rinoconjuntivite.","D":"A rubéola é causada por um vírua RNA da família Togaviridae e manifesta-se por manchas de\nKoplik na mucosa oral."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-174120","number":"174120","sourceNumber":"174120","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"No conjunto das doenças exantemáticas tóxicas nas crianças,","options":{"A":"a doença de Kawasaki ocorre primariamente após os cinco anos de idade e apresenta febre,\nlíngua em framboesa e plaquetose.","B":"a febre das montanhas rochosas é causada pela Rickettsia, adquirida através do carrapato, e\napresenta hiperemia conjuntival, mialgia e cefaleia temporal.","C":"a escarlatina ocorre entre os dois e os oito anos, é causada pelo Estreptococos do grupo A,\nprovocando febre, sinal de Pastia e palidez perioral.","D":"os sinais, como febre, trombocitose, hiperemia conjuntival, língua em framboesa e hipertensão,\nsão encontrados nos casos de síndrome do choque\ntóxico."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-136576","number":"136576","sourceNumber":"136576","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Dentre as doenças exantemáticas citadas a seguir, aponte aquela que NÃO seja\ncausada por vírus.","options":{"A":"Eritema infeccioso.","B":"Escarlatina.","C":"Rubéola.","D":"Sarampo atípico."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-35869","number":"35869","sourceNumber":"35869","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Pré-escolar de 5 anos é trazida à consulta por apresentar febre baixa e eritema em face\nhá 3 dias. Há 1 dia surgiu também eritema\nem face extensora de membros superiores. Mantém\nbom estado geral e apetite preservado. Refere artralgia nas mãos, punhos e joelhos. O diagnóstico\nmais provável é:","options":{"A":"Rubéola.","B":"Exantema súbito.","C":"Eritema infeccioso.","D":"Lúpus Eritematoso Sistêmico.","E":"Sarampo."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-35816","number":"35816","sourceNumber":"35816","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente de 25 anos, masculino, comerciante, apresentando febre, anorexia, cefaleia e\nmal-estar iniciados há 8 dias e há 5 dias com lesões exantemáticas de pele e mucosas,\nmaculopapular inicialmente, transformando-se em vesículas, com pleomorfismo evidente. Sua\nprimeira hipótese diagnóstica:","options":{"A":"Sarampo.","B":"Escarlatina.","C":"Varicela.","D":"Rubéola.","E":"Alergia."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-23063","number":"23063","sourceNumber":"23063","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Um lactente de oito meses de vida foi atendido no pronto-socorro, apresenta febre de\n39°C por 48 horas, com bom estado geral e\nsem nenhum outro sintoma. Exame físico normal. A\nmãe é orientada a manter o antitérmico e retornar em 24 horas para a reavaliação, ou antes, caso\napresente outro sintoma. Após 24 horas, o lactente é levado novamente ao pronto-socorro e apesar\nde não ter apresentado mais febre nas últimas seis horas, iniciou subitamente com erupção\ncutânea eritematosa, maculopapular, que desaparece à compressão e que vem progredindo no\nsentido cefalocaudal. O diagnóstico clínico, nesse caso, é:","options":{"A":"rubéola.","B":"sarampo.","C":"exantema súbito.","D":"eritema infeccioso."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-9334","number":"9334","sourceNumber":"9334","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente com 39 anos, imunocompetente, apresenta varicela com febre baixa e várias\nvesículas de distribuição universal. No dia seguinte, dá à luz um recém-nascido a termo. A conduta\nadequada em relação ao RN é:","options":{"A":"observar rigorosamente o RN nas próximas três semanas e introduzir aciclovir oral no primeiro\ndia da doença, caso evolua com varicela.","B":"iniciar aciclovir oral imediatamente.","C":"aplicar a vacina contra a varicela, pois é eficaz nestes casos, desde que administradas até o\nterceiro dia pós-contato.","D":"aplicar VZIG (imunoglobulina hiperimune antivaricela) em dose única intramuscular."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-11491","number":"11491","sourceNumber":"11491","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Pré-escolar apresentando palidez, sangramento retal moderado, dor abdominal com\nlesões hipercrômicas eritematopapulosas em nádegas e membros. Exames complementares:\nHemograma - discreta leucocitose, hematócrito 28, plaquetas normais. Dentre as hipóteses\ndiagnósticas mais prováveis:","options":{"A":"Talassemia minor.","B":"Neurofibromatose.","C":"Anemia de fanconi.","D":"Púrpura anafilactoide.","E":"Disceratose congênita."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-103910","number":"103910","sourceNumber":"103910","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Relacione as doenças exantemáticas da infância na COLUNA 1 com as suas\ncaracterísticas apresentadas na COLUNA 2 e, em\nseguida, escolha a opção que contém a\nsequência CORRETA. COLUNA 1: I. Sarampo; II. Rubéola; III. Escarlatina; IV. Eritema infeccioso;\n\nV. Exantema súbito. COLUNA 2: ( ) Eritema em todo o corpo, com pequenas pápulas; ( ) Período\nprodrômico com febre, conjuntivite, fotofobia; ( ) Causado pelo herpesvírus tipo 6; ( ) Evolução do\nexantema em três fases, recorrente; ( ) Exantema maculopapular róseo, início em face.","options":{"A":"I, IV, V, III e II.","B":"III, I, V, IV e II.","C":"II, I, III, IV e V.","D":"III, II, I, IV e V.","E":"III, I, IV, II e V."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-31892","number":"31892","sourceNumber":"31892","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Qual item abaixo NÃO faz parte dos critérios diagnósticos para a Doença de Kawasaki?","options":{"A":"Febre por mais de 5 dias.","B":"Aneurisma coronariano.","C":"Hiperemia conjuntival bilateral não purulenta.","D":"Adenomegalia cervical unilateral.","E":"Exantema maculopapular."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-25731","number":"25731","sourceNumber":"25731","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Paciente de 9 anos vai ao pediatra por apresentar há 4 dias vesículas sobre base\neritematosa agrupadas em hemitórax esquerdo,\nformando arranjo linear (distribuição em\ndermátomo). Refere dor e prurido discretos. Antecedentes mórbidos pessoais: Varicela com 1 ano,\n1 internação por pneumonia com 2 anos e asma. Diante do exposto, o diagnóstico mais provável é:","options":{"A":"Dermatite de contato","B":"Herpes zoster","C":"Impetigo bolhoso","D":"Molusco contagioso","E":"Herpes simples"},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-22651","number":"22651","sourceNumber":"22651","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Uma escolar de 6 anos vem ao pronto-socorro com história de febre alta há 24\nhoras, odinofagia, vômitos e cefaleia. Ao exame físico, apresenta-se em bom estado geral,\ncom hiperemia de faringe e adenomegalia cervical. O pediatra prescreve amoxicilina e, após\n\n24 horas, retorna com exantema maculopapular em tronco e face (exceto em região perioral).\n\nApresenta, ainda, hipertrofia de amígdalas com placas esbranquiçadas e língua bastante\nhiperemiada e sabugosa. O diagnóstico mais provável é:","options":{"A":"Mononucleose infecciosa.","B":"Eritema infeccioso.","C":"Escarlatina.","D":"Exantema súbito","E":"Sarampo."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-8776","number":"8776","sourceNumber":"8776","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"São critérios diagnósticos para a doença de Kawasaki todos os abaixo, exceto:","options":{"A":"Conjuntivite bilateral purulenta.","B":"Febre por 5 ou mais dias.","C":"Alterações da mucosa oral (vermelhidão dos lábios e da orofaringe, língua em framboesa).","D":"Edema de mãos ou de pés e descamação durante a convalescença.","E":"Linfadenomegalia cervical (maior que 1,5 cm de diâmetro), usualmente dolorosa."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-pediatria-med-ped-01-31472","number":"31472","sourceNumber":"31472","collectionBlock":"med:med-pediatria-med-ped-01","collectionLabel":"MED · MED PED 01","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"MED PED 01","subtopic":"","stem":"Lactente, 1 ano de idade, inicia com quadro súbito de febre alta (39ºC) contínua,\nirritabilidade e anorexia. Após 3 a 4 dias\ncessa a febre e surgem lesões maculopapulares rosadas\niniciando no tronco com disseminação para a face e extremidades. O diagnóstico mais provável é:","options":{"A":"Eritema infeccioso.","B":"Exantema súbito.","C":"Mononucleose infecciosa.","D":"Rubéola."},"answer":"","answerPending":true,"source":"Pediatria/MED PED 01/MED PED 01.txt","sourceLabel":"MED · MED PED 01","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","MED PED 01","MED"],"answerSource":"missing","commentDeferred":true}]};
